<template>
  <section ref="panel" class="questionnaire-panel" aria-label="问卷">
    <div v-if="loading" class="questionnaire-empty" role="status">正在打开问卷…</div>
    <div v-else-if="!record" class="questionnaire-empty" role="alert"><p>{{ loadError || '这份问卷暂时无法打开。' }}</p><button class="ui-button" type="button" @click="load">重试</button></div>
    <template v-else>
      <div class="questionnaire-scroll">
        <div class="questionnaire-body">
          <header class="questionnaire-heading">
            <div class="questionnaire-eyebrow"><span>问卷</span><span>来自 {{ ownerTitle || record.chatTitle || chatId }}</span></div>
            <h1>{{ record.title }}</h1>
            <p v-if="record.description" class="questionnaire-description">{{ record.description }}</p>
            <p v-if="record.status==='pending'" class="questionnaire-hint">已回答 {{ answeredCount }} / {{ visibleQuestions.length }} 题 · 填写内容自动保存</p>
            <p v-if="record.source" class="questionnaire-hint">{{ record.source.kind==='amendment'?'修改自':'使用模板' }}：{{ record.source.title }}<template v-if="record.source.kind==='amendment'"> · 原提交记录保留，提交修改后 Agent 会收到新答案，已执行的操作不会自动撤销。</template></p>
            <QuestionnaireTemplates :record="record" @open="openRecord" />
          </header>
          <div v-if="record.status==='submitted'" class="questionnaire-receipt" role="status"><AppIcon icon="check" /><div><strong>答案已提交</strong><p>{{ receiptTime }} · Agent 将根据这些答案继续。</p></div></div>
          <div v-else-if="record.status!=='pending'" class="questionnaire-notice" role="status">{{ record.status==='stale'?'这份问卷已结束，保留的内容仍可查看。':'问卷已取消，填写内容已保留。' }}</div>
          <div v-if="record.status==='pending'&&draft.conflict.value" class="questionnaire-notice" role="alert"><strong>草稿在另一处有更新</strong><p>当前输入和同步版本均已保留，请选择继续使用的版本。</p><div class="questionnaire-inline-actions"><button class="ui-button" type="button" :disabled="busy||draft.state.value==='saving'" @click="resolveConflict(true)">保留当前填写</button><button class="ui-button" type="button" :disabled="busy||draft.state.value==='saving'" @click="resolveConflict(false)">使用同步版本</button></div></div>
          <div v-if="record.status==='pending'&&!draft.conflict.value&&draft.recovery.value" class="questionnaire-recovery"><span>已保留一份冲突填写副本</span><button type="button" :disabled="busy" @click="draft.restoreRecovery()">恢复填写</button></div>
          <form v-if="record.status==='pending'" :id="formId" novalidate @submit.prevent="submit">
            <fieldset v-for="(question,index) in visibleQuestions" :key="question.id" :ref="element=>setQuestionElement(question.id,element)" class="questionnaire-question" :class="{'has-error':errors[question.id]}" :disabled="busy||uploading" tabindex="-1" :aria-describedby="errors[question.id]?`${formId}-${question.id}-error`:undefined">
              <legend><span class="questionnaire-number">{{ index+1 }}</span><span>{{ question.title }}<span v-if="question.required" class="questionnaire-required" aria-label="必填"> *</span></span></legend>
              <p v-if="question.description" class="questionnaire-question-description">{{ question.description }}</p>
              <div v-if="question.type==='single'||question.type==='multi'" class="questionnaire-options">
                <label v-for="option in question.options" :key="option.id" class="questionnaire-option" :class="{'is-checked':optionSelected(question,option.id)}"><input :type="question.type==='single'?'radio':'checkbox'" :name="`${formId}-${question.id}`" :checked="optionSelected(question,option.id)" @change="selectOption(question,option.id,($event.target as HTMLInputElement).checked)" /><span class="questionnaire-option-copy"><span>{{ option.label }}<small v-if="option.recommended" class="questionnaire-recommended">推荐</small></span><small v-if="option.description">{{ option.description }}</small></span></label>
                <label v-if="question.allowOther" class="questionnaire-option" :class="{'is-checked':otherSelected(question)}"><input :type="question.type==='single'?'radio':'checkbox'" :name="`${formId}-${question.id}`" :checked="otherSelected(question)" @change="toggleOther(question,($event.target as HTMLInputElement).checked)" /><span>其他，自行填写</span></label>
                <input v-if="question.allowOther&&otherSelected(question)" class="questionnaire-input questionnaire-other" type="text" :aria-label="`${question.title}：其他答案`" placeholder="填写你的想法" :value="answer(question.id).other||''" maxlength="10000" @input="update(question.id,{other:($event.target as HTMLInputElement).value})" />
              </div>
              <div v-else-if="question.type==='toggle'" class="questionnaire-toggle-group" role="radiogroup" :aria-label="question.title"><button v-for="choice in [true,false]" :key="String(choice)" class="questionnaire-toggle" type="button" role="radio" :aria-checked="answer(question.id).state==='answered'&&answer(question.id).value===choice" @click="setValue(question.id,choice)">{{ choice?'开启':'关闭' }}</button><span class="questionnaire-toggle-state">{{ answer(question.id).state==='unanswered'?'尚未选择':'' }}</span></div>
              <textarea v-else-if="question.type==='textarea'" class="questionnaire-input" rows="4" :aria-label="question.title" :placeholder="question.placeholder||'填写你的回答'" :value="textValue(question.id)" :disabled="specialState(question.id)||busy" maxlength="20000" @input="setText(question,($event.target as HTMLTextAreaElement).value)" />
              <div v-else-if="question.type==='number'" class="questionnaire-number-input"><input class="questionnaire-input" type="number" step="any" :aria-label="question.title" :placeholder="question.placeholder||'输入数字'" :min="question.min" :max="question.max" :value="textValue(question.id)" :disabled="specialState(question.id)||busy" @input="setNumber(question.id,($event.target as HTMLInputElement).value)" /><span v-if="question.unit">{{ question.unit }}</span></div>
              <input v-else-if="question.type==='date'" class="questionnaire-input" type="date" :aria-label="question.title" :min="question.minDate" :max="question.maxDate" :value="textValue(question.id)" :disabled="specialState(question.id)||busy" @input="setText(question,($event.target as HTMLInputElement).value)" />
              <div v-else-if="question.type==='dateRange'" class="questionnaire-date-range"><label>开始日期<input class="questionnaire-input" type="date" :aria-label="`${question.title}：开始日期`" :min="question.minDate" :max="question.maxDate" :value="answer(question.id).dateRange?.start||''" :disabled="specialState(question.id)||busy" @input="setDateRange(question.id,'start',($event.target as HTMLInputElement).value)" /></label><label>结束日期<input class="questionnaire-input" type="date" :aria-label="`${question.title}：结束日期`" :min="answer(question.id).dateRange?.start||question.minDate" :max="question.maxDate" :value="answer(question.id).dateRange?.end||''" :disabled="specialState(question.id)||busy" @input="setDateRange(question.id,'end',($event.target as HTMLInputElement).value)" /></label></div>
              <div v-else-if="question.type==='attachment'" class="questionnaire-attachments"><input class="questionnaire-input" type="file" :aria-label="question.title" :accept="question.accept?.join(',')" :multiple="(question.maxFiles??5)>1" :disabled="busy||uploading" @change="attachFiles(question,$event)" /><p class="questionnaire-hint">最多 {{ question.maxFiles??5 }} 个文件，每个不超过 {{ Math.round((question.maxFileBytes??MAX_QUESTIONNAIRE_FILE_BYTES)/1024) }} KB{{ question.accept?.length?'，支持 '+question.accept.join('、'):'' }}。添加后保存副本。</p><ul><li v-for="file in answer(question.id).attachments||[]" :key="file.id"><button type="button" class="questionnaire-text-button" :title="file.path" @click="openAttachment(file.id)">{{ file.name }}（{{ Math.ceil(file.size/1024) }} KB）</button><button type="button" class="questionnaire-text-button" :aria-label="`移除 ${file.name}`" @click="removeAttachment(question.id,file.id)">移除</button></li></ul><p v-if="uploading" role="status">正在保存附件…</p></div>
              <input v-else class="questionnaire-input" type="text" :aria-label="question.title" :placeholder="question.placeholder||'填写你的回答'" :value="textValue(question.id)" :disabled="specialState(question.id)||busy" maxlength="4000" @input="setText(question,($event.target as HTMLInputElement).value)" />
              <div class="questionnaire-answer-actions"><button v-if="question.allowUnknown" type="button" :aria-pressed="answer(question.id).state==='unknown'" @click="setState(question.id,'unknown')">不确定</button><button v-if="question.allowDelegate" type="button" :aria-pressed="answer(question.id).state==='delegate'" @click="setState(question.id,'delegate')">由 Agent 决定</button><button v-if="question.allowSkip" type="button" :aria-pressed="answer(question.id).state==='skip'" @click="setState(question.id,'skip')">跳过</button><button v-if="answer(question.id).state!=='unanswered'" type="button" @click="setState(question.id,'unanswered')">清除回答</button><button v-if="question.allowNote" type="button" :aria-expanded="notesOpen.has(question.id)" @click="toggleNote(question.id)">{{ notesOpen.has(question.id)?'收起备注':'添加备注' }}</button></div>
              <textarea v-if="question.allowNote&&(notesOpen.has(question.id))" class="questionnaire-input questionnaire-note" rows="2" :aria-label="`${question.title}：备注`" placeholder="补充这道题的说明（可选）" :value="answer(question.id).note||''" maxlength="10000" @input="update(question.id,{note:($event.target as HTMLTextAreaElement).value})" />
              <p v-if="errors[question.id]" :id="`${formId}-${question.id}-error`" class="questionnaire-error" role="alert">{{ errors[question.id] }}</p>
            </fieldset>
            <section class="questionnaire-supplement"><label :for="`${formId}-supplement`">还有什么需要补充？<span>可选</span></label><textarea :id="`${formId}-supplement`" class="questionnaire-input" rows="3" placeholder="未在题目中提到的想法、限制或建议…" :value="draft.supplement.value" :disabled="busy" maxlength="20000" @input="draft.edit(draft.answers.value,($event.target as HTMLTextAreaElement).value)" /><p v-if="errors['']" class="questionnaire-error" role="alert">{{ errors[''] }}</p></section>
          </form>
          <dl v-else class="questionnaire-summary"><template v-for="question in visibleQuestions" :key="question.id"><dt>{{ question.title }}</dt><dd>{{ summaryValue(question) }}<template v-if="question.type==='attachment'"><button v-for="file in receiptContent.answers[question.id]?.attachments||[]" :key="file.id" class="questionnaire-text-button" type="button" @click="openAttachment(file.id)">打开 {{ file.name }}</button></template></dd></template><template v-if="receiptContent.supplement"><dt>补充说明</dt><dd>{{ receiptContent.supplement }}</dd></template></dl>
          <section v-if="changes.length" class="questionnaire-changes" aria-label="答案修改对比"><h2>本次修改</h2><dl v-for="change in changes" :key="change.questionId"><dt>{{ change.title }}</dt><dd><span>原答案：{{ change.before }}</span><span>新答案：{{ change.after }}</span></dd></dl></section>
        </div>
      </div>
      <footer class="questionnaire-footer"><div class="questionnaire-footer-inner"><div class="questionnaire-save-status" :class="{'has-error':draft.state.value==='error'||draft.state.value==='conflict'}" role="status" aria-live="polite"><span>{{ footerStatus }}</span><button v-if="draft.state.value==='error'" type="button" @click="draft.flush()">重试</button></div><p v-if="actionError" class="questionnaire-error" role="alert">{{ actionError }}</p><div v-if="record.status==='pending'" class="questionnaire-footer-actions"><template v-if="confirmCancel"><span>取消后将结束本次等待，草稿保留。</span><button class="ui-button" type="button" @click="confirmCancel=false">继续填写</button><button class="ui-button" type="button" :disabled="busy" @click="cancel">确认取消</button></template><template v-else><button class="questionnaire-text-button" type="button" :disabled="busy" @click="confirmCancel=true">取消问卷</button><span class="questionnaire-footer-spacer" /><button class="ui-button" type="button" :disabled="busy" @click="returnToChat">切回聊天讨论</button><button class="ui-button primary" type="submit" :form="formId" :disabled="busy||uploading||!!draft.conflict.value">{{ busy?'正在提交…':record.source?.kind==='amendment'?'提交修改并继续':'提交并继续' }}<AppIcon icon="arrow-right" /></button></template></div><div v-else class="questionnaire-footer-actions"><button v-if="record.status==='submitted'" class="ui-button questionnaire-revise" type="button" :disabled="busy" @click="revise">修改答案</button><span class="questionnaire-footer-spacer" /><button class="ui-button" type="button" @click="returnToChat">返回对话</button></div></div></footer>
    </template>
  </section>
</template>

<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,toRef,useId,watch,type ComponentPublicInstance} from 'vue'
import AppIcon from './icons/AppIcon.vue'
import QuestionnaireTemplates from './QuestionnaireTemplates.vue'
import {requestOpenQuestionnaire} from '@/utils/questionnaire-events'
import {MAX_QUESTIONNAIRE_FILE_BYTES,visibleQuestionnaireQuestions,questionnaireAnswerChanges,formatQuestionnaireAnswers,validateQuestionnaireAnswers,type QuestionnaireAnswer,type QuestionnaireAnswerState,type QuestionnaireQuestion,type QuestionnaireRecord} from '@shared/questionnaire'
import {useQuestionnaireDraft} from '@/composables/useQuestionnaireDraft'
const props=defineProps<{questionnaireId:string;chatId:string;ownerTitle?:string}>()
const emit=defineEmits<{submitted:[record:QuestionnaireRecord];cancelled:[record:QuestionnaireRecord];returnToChat:[payload:{chatId:string;questionnaireId:string;message?:string}];notify:[message:string,color?:string]}>()
const panel=ref<HTMLElement|null>(null),record=ref<QuestionnaireRecord|null>(null),loading=ref(true),loadError=ref(''),busy=ref(false),actionError=ref(''),errors=ref<Record<string,string>>({}),notesOpen=ref(new Set<string>()),confirmCancel=ref(false)
const formId='questionnaire-'+useId(),draft=useQuestionnaireDraft(toRef(props,'questionnaireId')),questionElements=new Map<string,HTMLElement>()
const uploading=ref(false),original=ref<QuestionnaireRecord|null>(null)
let generation=0,submissionId=''
const compareRecords=(left:QuestionnaireRecord,right:QuestionnaireRecord)=>left.schemaRevision-right.schemaRevision||left.draft.revision-right.draft.revision||left.updatedAt-right.updatedAt
function receiveRecord(updated:QuestionnaireRecord){const previous=record.value;if(previous?.id===updated.id&&compareRecords(updated,previous)<0)return;record.value=updated;draft.acceptRemote(updated)}
async function load(){const run=++generation;loading.value=true;loadError.value='';actionError.value='';errors.value={};confirmCancel.value=false;submissionId='';try{const result=await window.navora!.questionnaires.get(props.questionnaireId);if(run!==generation)return;if(!result||result.chatId!==props.chatId)throw Error('问卷不存在或不属于当前对话');const previous=record.value,latest=previous&&previous.id===result.id&&compareRecords(previous,result)>0?previous:result;record.value=latest;draft.load(latest);notesOpen.value=new Set(Object.keys(draft.answers.value).filter(id=>!!draft.answers.value[id]?.note))}catch(error){if(run===generation){record.value=null;loadError.value=error instanceof Error?error.message:'问卷暂时无法打开'}}finally{if(run===generation)loading.value=false}}
watch(()=>[props.questionnaireId,props.chatId],()=>{original.value=null;void load()},{immediate:true})
watch(()=>record.value?.source?.kind==='amendment'?record.value.source.id:undefined,async id=>{original.value=null;if(!id)return;try{const source=await window.navora!.questionnaires.get(id);if(record.value?.source?.id===id)original.value=source}catch{/* The amendment draft remains available even if the original cannot be read. */}})
watch(draft.record,updated=>{const previous=record.value;if(updated&&updated.id===props.questionnaireId&&updated.chatId===props.chatId&&(!previous||previous.id!==updated.id||compareRecords(updated,previous)>=0))record.value=updated})
const unsubscribe=window.navora?.questionnaires.onChanged(updated=>{if(updated.id!==props.questionnaireId||updated.chatId!==props.chatId)return;receiveRecord(updated)})
onBeforeUnmount(()=>{generation++;unsubscribe?.()})
const answer=(id:string):QuestionnaireAnswer=>draft.answers.value[id]||{state:'unanswered'}
const specialState=(id:string)=>!['answered','unanswered'].includes(answer(id).state)
const textValue=(id:string)=>answer(id).value===undefined?'':String(answer(id).value)
function update(id:string,patch:Partial<QuestionnaireAnswer>){draft.edit({...draft.answers.value,[id]:{...answer(id),...patch}},draft.supplement.value);delete errors.value[id];actionError.value=''}
function setValue(id:string,value:QuestionnaireAnswer['value']){update(id,{state:'answered',value})}
function setText(question:QuestionnaireQuestion,value:string){update(question.id,value?{state:'answered',value}:{state:'unanswered',value:undefined})}
function setNumber(id:string,value:string){update(id,value.trim()&&Number.isFinite(Number(value))?{state:'answered',value:Number(value)}:{state:'unanswered',value:undefined})}
function setState(id:string,state:QuestionnaireAnswerState){update(id,{state:answer(id).state===state?'unanswered':state,value:undefined,other:undefined,dateRange:undefined,attachments:undefined})}
function setDateRange(id:string,part:'start'|'end',value:string){const dateRange={start:'',end:'',...answer(id).dateRange,[part]:value};update(id,dateRange.start||dateRange.end?{state:'answered',dateRange,value:undefined}:{state:'unanswered',dateRange:undefined,value:undefined})}
async function attachFiles(question:QuestionnaireQuestion,event:Event){
  const input=event.target as HTMLInputElement,files=Array.from(input.files||[]),id=props.questionnaireId,existing=answer(question.id).attachments||[]
  if(!files.length||uploading.value)return
  uploading.value=true;actionError.value=''
  try{
    if(files.length+existing.length>(question.maxFiles??5)||files.some(f=>f.size>(question.maxFileBytes??MAX_QUESTIONNAIRE_FILE_BYTES)||question.accept?.length&&!question.accept.some(ext=>f.name.toLowerCase().endsWith(ext.toLowerCase()))))throw Error('附件数量、大小或文件类型不符合题目要求。')
    const payload=await Promise.all(files.map(async file=>{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return{name:file.name,data:btoa(binary)}}))
    const attached=await window.navora!.questionnaires.attach(id,question.id,payload)
    if(props.questionnaireId!==id)return
    update(question.id,{state:'answered',attachments:[...existing,...attached],value:undefined});await draft.flush()
  }catch(e){if(props.questionnaireId===id)actionError.value=e instanceof Error?e.message:'附件保存失败，请重试。'}finally{uploading.value=false;input.value=''}
}
function removeAttachment(id:string,fileId:string){const attachments=(answer(id).attachments||[]).filter(f=>f.id!==fileId);update(id,attachments.length?{state:'answered',attachments}:{state:'unanswered',attachments:undefined})}
async function openAttachment(id:string){try{await window.navora!.questionnaires.openAttachment(props.questionnaireId,id)}catch(e){actionError.value=e instanceof Error?e.message:'附件暂时无法打开。'}}
function openRecord(next:QuestionnaireRecord){requestOpenQuestionnaire(next.id,next.chatId)}
async function revise(){if(busy.value||!record.value)return;busy.value=true;actionError.value='';try{openRecord(await window.navora!.questionnaires.revise(record.value.id))}catch(e){actionError.value=e instanceof Error?e.message:'暂时无法修改答案。'}finally{busy.value=false}}
function optionSelected(q:QuestionnaireQuestion,id:string){const value=answer(q.id);return value.state==='answered'&&(q.type==='single'?value.value===id:Array.isArray(value.value)&&value.value.includes(id))}
function selectOption(q:QuestionnaireQuestion,id:string,checked:boolean){const previous=answer(q.id);if(q.type==='single')update(q.id,{state:'answered',value:id,other:undefined});else{const values=previous.state==='answered'&&Array.isArray(previous.value)?previous.value:[],value=checked?[...new Set([...values,id])]:values.filter(item=>item!==id),other=previous.state==='answered'?previous.other:undefined;update(q.id,value.length||other!==undefined?{state:'answered',value,other}:{state:'unanswered',value:undefined,other:undefined})}}
function otherSelected(q:QuestionnaireQuestion){return answer(q.id).state==='answered'&&answer(q.id).other!==undefined}
function toggleOther(q:QuestionnaireQuestion,checked:boolean){const previous=answer(q.id);if(q.type==='single')update(q.id,checked?{state:'answered',value:'',other:''}:{state:'unanswered',value:undefined,other:undefined});else{const value=previous.state==='answered'&&Array.isArray(previous.value)?previous.value:[];update(q.id,checked||value.length?{state:'answered',value,other:checked?'':undefined}:{state:'unanswered',value:undefined,other:undefined})}}
function toggleNote(id:string){const next=new Set(notesOpen.value);if(next.has(id))next.delete(id);else next.add(id);notesOpen.value=next}
function setQuestionElement(id:string,element:Element|ComponentPublicInstance|null){if(element instanceof HTMLElement)questionElements.set(id,element);else questionElements.delete(id)}
async function showErrors(values:Array<{questionId:string;message:string}>){errors.value=Object.fromEntries(values.map(error=>[error.questionId,error.message]));await nextTick();const target=questionElements.get(values[0]?.questionId||'');target?.scrollIntoView({block:'center',behavior:'instant'});(target?.querySelector<HTMLElement>('input:not(:disabled),textarea:not(:disabled),button:not(:disabled)')||target)?.focus({preventScroll:true})}
async function flushDraft(){return !uploading.value&&await draft.flush()}
async function resolveConflict(useLocal:boolean){if(busy.value)return;busy.value=true;try{if(await draft.resolveConflict(useLocal)){errors.value={};notesOpen.value=new Set(Object.keys(draft.answers.value).filter(id=>!!draft.answers.value[id]?.note))}}finally{busy.value=false}}
async function submit(){if(busy.value||uploading.value||!record.value||record.value.status!=='pending')return;const invalid=validateQuestionnaireAnswers(record.value.questions,draft.answers.value,draft.supplement.value);if(invalid.length){await showErrors(invalid);return}busy.value=true;actionError.value='';try{if(!await draft.flush()){actionError.value='请先保存草稿或处理版本冲突，再提交。';return}submissionId ||= crypto.randomUUID();const result=await window.navora!.questionnaires.submit(props.questionnaireId,{revision:draft.revision.value,submissionId,answers:JSON.parse(JSON.stringify(draft.answers.value)),supplement:draft.supplement.value});record.value=result.record;draft.acceptRemote(result.record);if(!result.ok){if(result.errors?.length)await showErrors(result.errors);actionError.value=result.error||'提交未完成，填写内容仍已保留。';return}emit('submitted',result.record)}catch(error){console.warn('[questionnaire] submit failed',error);actionError.value='提交暂时失败，填写内容已保留，请重试。'}finally{busy.value=false}}
async function cancel(){if(busy.value||!record.value)return;busy.value=true;actionError.value='';try{if(!await draft.flush()){actionError.value='请先保存草稿或处理版本冲突。';return}const result=await window.navora!.questionnaires.cancel(props.questionnaireId,'cancelled');record.value=result.record;if(!result.ok){actionError.value=result.error||'暂时无法取消，请重试。';return}confirmCancel.value=false;emit('cancelled',result.record)}catch{actionError.value='暂时无法取消，草稿已保留。'}finally{busy.value=false}}
async function returnToChat(){if(uploading.value){actionError.value='附件正在保存，请稍候。';return}if(record.value?.status==='pending'&&!await draft.flush()){actionError.value='请先保存草稿或处理版本冲突。';return}emit('returnToChat',{chatId:props.chatId,questionnaireId:props.questionnaireId})}
const visibleQuestions=computed(()=>visibleQuestionnaireQuestions(record.value?.questions||[],record.value?.status==='submitted'?record.value.submission?.answers||{}:draft.answers.value))
const answeredCount=computed(()=>visibleQuestions.value.filter(q=>answer(q.id).state!=='unanswered').length)
const receiptContent=computed(()=>record.value?.submission||{answers:draft.answers.value,supplement:draft.supplement.value})
const changes=computed(()=>original.value?.submission&&record.value?questionnaireAnswerChanges(record.value.questions,original.value.submission.answers,receiptContent.value.answers,original.value.submission.supplement,receiptContent.value.supplement):[])
const receiptTime=computed(()=>record.value?.submission?new Date(record.value.submission.submittedAt).toLocaleString(): '')
function summaryValue(question:QuestionnaireQuestion){const text=formatQuestionnaireAnswers([{...question,showWhen:undefined}],receiptContent.value.answers);return text.slice(question.title.length+1)}
